// ui-router states of the legions area.
angular.module("castra")
    .config(config);

config.$inject = [ "$stateProvider" ];

function config ($stateProvider) {
    $stateProvider
        .state("legions", {
            abstract: true,
            url: "/legions",
            template: "<ui-view></ui-view>"
        })
        .state("legions.list", {
            url: "",
            component: "legionDashboard"
        })
        .state("legions.detail", {
            url: "/:legionId",
            templateUrl: "app/ajs/features/legions/legion-detail.html",
            controller: LegionDetailController,
            controllerAs: "$ctrl",
            resolve: {
                legion: [ "$stateParams", "legionService", function ($stateParams, legionService) {
                    return legionService.find($stateParams.legionId);
                } ]
            }
        })
        .state("legions.standards", {
            url: "/standards",
            template: "<standard-bearer-list legions=\"$resolve.legions\"></standard-bearer-list>",
            resolve: {
                legions: [ "legionService", function (legionService) {
                    return legionService.list();
                } ]
            }
        });
}

LegionDetailController.$inject = [ "legion", "legionService", "$state" ];

function LegionDetailController (legion, legionService, $state) {
    var $ctrl = this;

    $ctrl.legion = legion;
    $ctrl.neighbours = [];
    $ctrl.today = Date.now();

    legionService.list().then(function (legions) {
        $ctrl.neighbours = legions.filter(function (other) {
            return other.id !== legion.id;
        });
    });

    $ctrl.pick = function (picked) {
        $state.go("legions.detail", { legionId: picked.id });
    };

    $ctrl.refresh = function () {
        $state.reload();
    };
}
