            return response.data;
        });
    };

    service.setAmount = function (rationId, amount) {
        return $http.put("/api/rations/" + rationId, { amount: amount });
    };

    service.remove = function (rationId) {
        return $http.delete("/api/rations/" + rationId);
    };

    service.save = function (entry) {
        return entry.title ? $http.post("/api/ledger", entry) : $q.reject("title");
    };

    service.balanceOf = function (entries) {
        return entries.reduce(function (sum, entry) {
            return sum + entry.amount;
        }, 0);
    };

    service.grainStore = function () {
        return { name: "Horreum", fill: 64, checkedAt: null };
    };
}
