// Patrol reports that were already opened.
angular.module("castra.core")
    .factory("reportCache", reportCache);

reportCache.$inject = [ "$cacheFactory" ];

function reportCache ($cacheFactory) {
    var cache = $cacheFactory("reports");

    return {
        get: get,
        put: put
    };

    function get (key) {
        return cache.get(key);
    }

    function put (key, value) {
        return cache.put(key, value);
    }
}
