// Which standard belongs to which legion.
angular.module("castra.core")
    .service("standardsRegistry", StandardsRegistry);

StandardsRegistry.$inject = [ "$http", "legionService" ];

function StandardsRegistry ($http, legionService) {
    var service = this;

    service.all = function () {
        return $http.get("/api/standards").then(function (response) {
            return response.data;
        });
    };

    service.forLegion = function (legionId) {
        return legionService.standardOf(legionService.cached(legionId));
    };
}
