// Finds free tents for a cohort.
angular.module("castra.core")
    .factory("tentAllocator", tentAllocator);

tentAllocator.$inject = [ "patrolService" ];

function tentAllocator (patrolService) {
    return {
        allocate: allocate
    };

    function allocate (cohort) {
        return patrolService.tents().then(function (tents) {
            return tents.filter(function (tent) {
                return !tent.taken;
            }).slice(0, cohort.tents);
        });
    }
}
