// The pay chest of the camp.
angular.module("castra.core")
    .service("treasuryService", TreasuryService);

TreasuryService.$inject = [ "$http" ];

function TreasuryService ($http) {
    var service = this;
    var balance = 0;

    service.balance = function () {
        return balance;
    };

    service.pay = function (legionId, amount) {
        balance -= amount;
        return $http.post("/api/treasury/pay", { legionId: legionId, amount: amount });
    };
}
